import{_ as t,o as a,c as r,a0 as s}from"./chunks/framework.Cg_noeTw.js";const g=JSON.parse('{"title":"Boundaries","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/boundaries.md","filePath":"explanation/boundaries.md"}'),o={name:"explanation/boundaries.md"};function n(i,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h1><p>Scarab owns two things: <strong>config loading</strong> (discovery + formats, generic over the model) and <strong>templated content packs</strong> (the <code>type: template</code> driver). Everything adjacent belongs to a neighbor.</p><h2 id="neighbors" tabindex="-1">Neighbors <a class="header-anchor" href="#neighbors" aria-label="Permalink to &quot;Neighbors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Repo</th><th>Owns</th><th>Scarab&#39;s relation</th></tr></thead><tbody><tr><td><strong>tamias</strong></td><td>Content distribution — refs, fetch, store, install pipeline, driver dispatch</td><td>Scarab ships <em>inside</em> tamias&#39;s world: <code>tamias-driver-template</code> is a content driver; template packs are tamias packages. Scarab never reimplements fetch/install/store.</td></tr><tr><td><strong>cuora</strong></td><td>Secret values — sealed, not spilled</td><td>Config carries secret <em>names</em>, never values. A template var named <code>api_key</code> holds a reference/name; cuora resolves it.</td></tr><tr><td><strong>tarsi</strong></td><td>Release plane — changelog → bump → tag → publish</td><td>A consumer: <code>tarsi.toml</code>/profile loading rides <code>scarab-config</code>.</td></tr><tr><td><strong>myco / kuda / mimus</strong></td><td>Work ledger, code-map, verification</td><td>Consumers of the config port for their own <code>&lt;name&gt;.yaml</code>/<code>.toml</code> discovery — the exact problem P-017 generalized.</td></tr><tr><td><strong>hypha</strong></td><td>Pure distributed substrate</td><td>The P-015 config crates were ported <em>here</em>, not kept there — hypha stays substrate-only.</td></tr><tr><td><strong>peregrin / sepia / pavo</strong></td><td>Orchestration, sessions, agent UI</td><td>May consume either plane; neither defines scarab&#39;s contracts.</td></tr></tbody></table><h2 id="what-scarab-deliberately-is-not" tabindex="-1">What scarab deliberately is not <a class="header-anchor" href="#what-scarab-deliberately-is-not" aria-label="Permalink to &quot;What scarab deliberately is not&quot;">​</a></h2><ul><li><strong>Not a config schema registry.</strong> It loads and renders; it doesn&#39;t validate semantics. Your serde model <em>is</em> the schema.</li><li><strong>Not a secrets store.</strong> See cuora above — the boundary is enforced by convention (<code>secret names, never values</code>) and by cuora owning resolution.</li><li><strong>Not a template marketplace.</strong> Packs are ordinary tamias packages; distribution, provenance, and digests are tamias&#39;s job.</li><li><strong>Not consumer-aware.</strong> No crate in scarab may name another repo&#39;s <code>Config</code> type — that coupling is what the port exists to prevent.</li></ul><h2 id="the-naming-story" tabindex="-1">The naming story <a class="header-anchor" href="#the-naming-story" aria-label="Permalink to &quot;The naming story&quot;">​</a></h2><p><em>Scarabaeus sacer</em> — the sacred scarab rolls the ball into place; scarab amulets were seals and signets. Config as the seal that validates what runs: discovery finds the right file, the format parses it, the model validates it. Design history lives in the org ledger — proposal P-017 (supersedes P-015).</p>',8)])])}const p=t(o,[["render",n]]);export{g as __pageData,p as default};
